-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.accept_legal(terms_version text, privacy_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_at timestamptz;
begin
  if v_user is null or not public.token_session_open() then
    raise exception 'session_closed' using errcode = '28000';
  end if;
  insert into public.legal_acceptances (user_id, terms_version, privacy_version)
  values (v_user, accept_legal.terms_version, accept_legal.privacy_version)
  on conflict do nothing;
  select a.accepted_at into v_at from public.legal_acceptances a
   where a.user_id = v_user
     and a.terms_version = accept_legal.terms_version
     and a.privacy_version = accept_legal.privacy_version;
  return jsonb_build_object('accepted_at', v_at);
end;
$function$;

grant execute on function public.accept_legal(terms_version text, privacy_version text) to authenticated;
grant execute on function public.accept_legal(terms_version text, privacy_version text) to service_role;
